sp_widget.client_script:
api.controller = function($scope, $uibModal, spUtil) {
    var c = this;
    c.search = "";

    /* =====================================================
       PAGINATION
    ===================================================== */
    c.page      = 1;
    c.pageSize  = 10;
    c.pageSizes = [5, 10, 25, 50];
    c.filtered  = [];

    c.totalItems = function() {
        return c.search ? (c.filtered || []).length
                        : (c.data.patients || []).length;
    };

    c.totalPages = function() {
        return Math.max(1, Math.ceil(c.totalItems() / c.pageSize));
    };

    c.endIndex = function() {
        return Math.min(c.page * c.pageSize, c.totalItems());
    };

    c.goToPage = function(n) {
        if (n < 1 || n > c.totalPages()) return;
        c.page = n;
    };

    // Max 5 page buttons, windowed around the current page
    c.pageNumbers = function() {
        var total = c.totalPages();
        var start = Math.max(1, c.page - 2);
        var end   = Math.min(total, start + 4);
        start     = Math.max(1, end - 4);
        var pages = [];
        for (var i = start; i <= end; i++) pages.push(i);
        return pages;
    };

    // Clamp page when records are deleted or search narrows results
    $scope.$watch(function() { return c.totalItems(); }, function() {
        if (c.page > c.totalPages()) c.page = c.totalPages();
    });

    /* =====================================================
       HELPERS
    ===================================================== */

    function openModal() {
        return $uibModal.open({
            templateUrl: 'patientModal',
            scope: $scope,
            size: 'lg'
        });
    }

    // <input type="date"> needs a JS Date object
    function toDateObject(yyyyMMdd) {
        if (!yyyyMMdd) return null;
        var parts = yyyyMMdd.split('-');
        return new Date(parts[0], parts[1] - 1, parts[2]);
    }

    // ...and the server needs it back as "yyyy-MM-dd"
    function toDateString(d) {
        if (!d) return '';
        if (typeof d === 'string') return d;
        var m  = ('0' + (d.getMonth() + 1)).slice(-2);
        var dd = ('0' + d.getDate()).slice(-2);
        return d.getFullYear() + '-' + m + '-' + dd;
    }

    function buildPayload(p) {
        return {
            sys_id:         p.sys_id || '',
            number:         p.number || '',
            patient_name:   p.patient_name || '',
            dob:            toDateString(p.dob),
            gender:         p.gender || '',
            diagnosis:      p.diagnosis || '',
            primary_doctor: p.primary_doctor || '',
            care_facility:  p.care_facility || '',
            guardian:       p.guardian || '',
            caregiver:      p.caregiver || ''
        };
    }

    /* =====================================================
       CREATE
    ===================================================== */
    c.openPatientModal = function() {
        $scope.modalTitle = "Create Patient";
        $scope.patient = {};

        var modal = openModal();

        $scope.savePatient = function() {
            if (!$scope.patient.patient_name) {
                spUtil.addErrorMessage('Patient Name is required');
                return;
            }
            c.server.get({
                action: 'create',
                patient: buildPayload($scope.patient)
            }).then(function(r) {
                c.data.patients = r.data.patients;
                modal.close();
                spUtil.addInfoMessage('Patient created successfully');
            });
        };
    };

    /* =====================================================
       EDIT
    ===================================================== */
    c.editPatient = function(patient) {
        $scope.modalTitle = "Edit Patient";

        // copy the REAL fields of this widget
        $scope.patient = angular.copy(patient);
        $scope.patient.dob = toDateObject(patient.dob);

        var modal = openModal();

        $scope.savePatient = function() {
            c.server.get({
                action: 'update',
                patient: buildPayload($scope.patient)
            }).then(function(r) {
                c.data.patients = r.data.patients;
                modal.close();
                spUtil.addInfoMessage('Patient updated successfully');
            });
        };
    };

    /* =====================================================
       DELETE  (was missing entirely)
    ===================================================== */
    c.deletePatient = function(patient) {
        if (!confirm('Delete patient "' + patient.patient_name + '"? This cannot be undone.')) {
            return;
        }
        c.server.get({
            action: 'delete',
            sys_id: patient.sys_id
        }).then(function(r) {
            c.data.patients = r.data.patients;
            spUtil.addInfoMessage('Patient deleted');
        });
    };
};

sp_widget.css:
/* ==========================================
   PAGE
========================================== */

.tm-page{
    padding:20px;
    background:#f1f5f9;
}

/* ==========================================
   HEADER
========================================== */

.tm-header{
    display:flex;
    justify-content:space-between;
    align-items:center;

    padding:24px 30px;

    margin-bottom:20px;

    background:linear-gradient(
        135deg,
        #2563eb,
        #4f46e5
    );

    border-radius:20px;

    color:#fff;

    box-shadow:0 15px 35px rgba(37,99,235,.25);
}

.tm-header h2{
    margin:0;
    font-size:28px;
    font-weight:700;
}

.tm-header p{
    margin:5px 0 0;
    opacity:.9;
    font-size:14px;
}

/* ==========================================
   CREATE BUTTON
========================================== */

.tm-create-btn{
    background:linear-gradient(
        135deg,
        #06b6d4,
        #0891b2
    ) !important;

    color:#fff !important;

    border:none !important;

    border-radius:12px;

    padding:10px 18px;

    font-weight:600;

    transition:.3s;

    box-shadow:0 10px 25px rgba(8,145,178,.3);
}

.tm-create-btn:hover{
    transform:translateY(-2px);
}

/* ==========================================
   SEARCH
========================================== */

.tm-search-section{
    margin-bottom:18px;
}

.tm-search-wrapper{
    position:relative;
}

.tm-search-wrapper i{
    position:absolute;
    left:18px;
    top:18px;
    color:#94a3b8;
}

.tm-search{
    width:100%;
    height:54px;

    border:none;

    border-radius:16px;

    padding-left:48px;

    background:#fff;

    box-shadow:
    0 5px 20px rgba(0,0,0,.05);
}

.tm-search:focus{
    outline:none;

    box-shadow:
    0 0 0 4px rgba(37,99,235,.15);
}

/* ==========================================
   TABLE WRAPPER
========================================== */

.tm-table-wrapper{
    background:#fff;

    border-radius:20px;

    overflow:hidden;

    border:1px solid #e2e8f0;

    box-shadow:
    0 10px 30px rgba(15,23,42,.08);
}

/* ==========================================
   TABLE
========================================== */

.tm-table{
    margin:0;
}

.tm-table thead{
    background:
    linear-gradient(
        135deg,
        #2563eb,
        #4f46e5
    );
}

.tm-table thead th{
    color:#fff !important;

    padding:12px 16px;

    border:none !important;

    font-size:12px;

    font-weight:700;

    text-transform:uppercase;

    letter-spacing:.5px;
}

.tm-table tbody tr{
    transition:.25s;
}

.tm-table tbody tr:nth-child(even){
    background:#f8fafc;
}

.tm-table tbody tr:hover{
    background:#eff6ff !important;
    box-shadow:inset 4px 0 0 #2563eb;
}

.tm-table tbody td{
    padding:10px 16px;

    border-top:none !important;

    border-bottom:1px solid #eef2f7;

    vertical-align:middle;

    color:#334155;
}

/* ==========================================
   PATIENT AVATAR
========================================== */

.tm-patient-name{
    display:flex;
    align-items:center;
    gap:10px;
}

.tm-avatar{
    width:34px;
    height:34px;

    border-radius:50%;

    display:flex;
    align-items:center;
    justify-content:center;

    color:white;

    font-size:13px;

    font-weight:700;

    background:
    linear-gradient(
        135deg,
        #2563eb,
        #7c3aed
    );
}

.tm-name{
    font-weight:700;
    color:#0f172a;
}

/* ==========================================
   ID BADGE
========================================== */

.tm-id-badge{
    background:#dbeafe;

    color:#1d4ed8;

    padding:4px 10px;

    border-radius:999px;

    font-size:11px;

    font-weight:700;
}

/* ==========================================
   GENDER BADGE
========================================== */

.tm-gender{
    background:#ede9fe;

    color:#6d28d9;

    padding:4px 10px;

    border-radius:999px;

    font-size:11px;

    font-weight:700;
}

/* ==========================================
   DIAGNOSIS
========================================== */

.tm-diagnosis{
    background:#fef3c7;

    color:#92400e;

    padding:4px 10px;

    border-radius:999px;

    font-size:11px;

    font-weight:600;
}

/* ==========================================
   DOCTOR
========================================== */

.tm-doctor{
    color:#2563eb;
    font-weight:600;
}

.tm-doctor i{
    margin-right:4px;
}

/* ==========================================
   EDIT BUTTON
========================================== */

.tm-edit-btn{
    background:linear-gradient(
        135deg,
        #0ea5e9,
        #0284c7
    ) !important;

    color:#fff !important;

    border:none !important;

    border-radius:8px;

    padding:4px 10px;
}

/* ==========================================
   DELETE BUTTON
========================================== */

.tm-delete-btn{
    background:linear-gradient(
        135deg,
        #ef4444,
        #dc2626
    ) !important;

    color:#fff !important;

    border:none !important;

    border-radius:8px;

    padding:4px 10px;
}

/* ==========================================
   STATUS
========================================== */

.tm-status{
    display:inline-flex;
    align-items:center;
    gap:6px;

    padding:4px 10px;

    border-radius:999px;

    font-size:11px;

    font-weight:700;
}

.tm-status-active{
    background:#dcfce7;
    color:#166534;
}

.tm-status-critical{
    background:#fee2e2;
    color:#991b1b;
}

.tm-status-pending{
    background:#fef3c7;
    color:#92400e;
}

.tm-status-inactive{
    background:#e2e8f0;
    color:#475569;
}

/* ==========================================
   EMPTY STATE
========================================== */

.tm-empty{
    text-align:center;
    padding:50px;
    color:#64748b;
}

.tm-empty i{
    font-size:48px;
    color:#cbd5e1;
    margin-bottom:10px;
}

/* ==========================================
   PAGINATION
========================================== */

.tm-pagination{
    display:flex;
    justify-content:space-between;
    align-items:center;

    flex-wrap:wrap;

    gap:15px;

    padding:15px 20px;

    background:#f8fafc;

    border-top:1px solid #e2e8f0;
}

.tm-page-info{
    color:#64748b;
    font-size:13px;
}

.tm-page-size{
    border:none;

    background:white;

    padding:6px 10px;

    border-radius:8px;
}

.tm-pager{
    margin:0;
}

.tm-pager > li > a{
    border:none;

    background:white;

    border-radius:8px;

    margin:0 2px;

    min-width:34px;

    color:#475569;
}

.tm-pager > li.active > a{
    background:#2563eb;
    color:white;
}

.tm-pager > li > a:hover{
    background:#dbeafe;
}

/* ==========================================
   RESPONSIVE
========================================== */

@media(max-width:768px){

    .tm-header{
        flex-direction:column;
        gap:15px;
        text-align:center;
    }

    .tm-create-btn{
        width:100%;
    }

    .tm-pagination{
        flex-direction:column;
    }
}

sp_widget.script:
(function() {

    var TABLE = 'x_snc_trackmed_patient_record';

    /* =====================================================
       ⚠️ ADJUST THESE TWO THINGS:

       1) USER_TYPE_FIELD — the column name of your user
          type field on sys_user. Find it: open a user
          record → right-click the "User Type" label →
          Configure Dictionary → copy the "Column name"
          (e.g. u_user_type, x_snc_trackmed_user_type).

       2) The type VALUES below — if it's a choice field,
          use the choice *value* (often lowercase), not
          the label. Right-click the field → Show Choice
          List to see the values.
    ===================================================== */
    var USER_TYPE_FIELD = 'x_snc_trackmed_user_type';

    var USER_TYPES = {
        doctor:    'doctor',
        facility:  'organization_admin',
        guardian:  'guardian',
        caregiver: 'care_taker'
    };

    if (input) {

        /* ---------- CREATE ---------- */
        if (input.action == 'create' && input.patient) {
            var grCreate = new GlideRecord(TABLE);
            grCreate.initialize();
            setFields(grCreate, input.patient);
            grCreate.insert();
        }

        /* ---------- UPDATE ---------- */
        if (input.action == 'update' && input.patient && input.patient.sys_id) {
            var grUpdate = new GlideRecord(TABLE);
            if (grUpdate.get(input.patient.sys_id)) {
                setFields(grUpdate, input.patient);
                grUpdate.update();
            }
        }

        /* ---------- DELETE ---------- */
        if (input.action == 'delete' && input.sys_id) {
            var grDelete = new GlideRecord(TABLE);
            if (grDelete.get(input.sys_id)) {
                grDelete.deleteRecord();
            }
        }
    }

    /* =====================================================
       DROPDOWN OPTIONS — all from sys_user,
       filtered by user type
    ===================================================== */
    data.doctors    = getUsersByType(USER_TYPES.doctor);
    data.facilities = getUsersByType(USER_TYPES.facility);
    data.guardians  = getUsersByType(USER_TYPES.guardian);
    data.caregivers = getUsersByType(USER_TYPES.caregiver);

    /* =====================================================
       PATIENT LIST
       Reference fields send BOTH:
       - getValue()        → sys_id (pre-selects edit dropdowns)
       - getDisplayValue() → name   (shown in table cells)
    ===================================================== */
    data.patients = [];
    var gr = new GlideRecord(TABLE);
    gr.orderBy('patient_name');
    gr.query();
    while (gr.next()) {
        data.patients.push({
            sys_id:       gr.getUniqueValue(),
            number:       gr.getValue('number'),
            patient_name: gr.getValue('patient_name'),
            dob:          gr.getValue('dob'),
            gender:       gr.getDisplayValue('gender'),
            diagnosis:    gr.getValue('diagnosis'),

            primary_doctor:         gr.getValue('primary_doctor'),
            primary_doctor_display: gr.getDisplayValue('primary_doctor'),

            care_facility:          gr.getValue('care_facility'),
            care_facility_display:  gr.getDisplayValue('care_facility'),

            guardian:               gr.getValue('guardian'),
            guardian_display:       gr.getDisplayValue('guardian'),

            caregiver:              gr.getValue('caregiver'),
            caregiver_display:      gr.getDisplayValue('caregiver')
        });
    }

    /* ---------- HELPERS ---------- */

    function getUsersByType(typeValue) {
        var list = [];
        var u = new GlideRecord('sys_user');
        u.addActiveQuery();                       // skip deactivated users
        u.addQuery(USER_TYPE_FIELD, typeValue);
        u.orderBy('name');
        u.query();
        while (u.next()) {
            list.push({
                sys_id: u.getUniqueValue(),
                name:   u.getValue('name')
            });
        }
        return list;
    }

    function setFields(gr, p) {
        gr.number       = p.number;
        gr.patient_name = p.patient_name;
        gr.dob          = p.dob;
        gr.diagnosis    = p.diagnosis;
        gr.setDisplayValue('gender', p.gender);

        // sys_ids straight from the dropdowns
        gr.primary_doctor = p.primary_doctor || '';
        gr.care_facility  = p.care_facility  || '';
        gr.guardian       = p.guardian       || '';
        gr.caregiver      = p.caregiver      || '';
    }

})();
